import { cookies, headers } from 'next/headers'

export default async function ThemeDisplay() {
  const cookieStore = await cookies()
  const theme = cookieStore.get('theme')?.value || 'light'

  const headersList = await headers()
  const acceptLanguage = headersList.get('accept-language')

  return (
    <div className="p-4 border rounded shadow-sm">
      <h2 className="text-xl font-bold mb-2">User Preferences</h2>
      <div className="space-y-2">
        <p>
          <span className="font-semibold">Current Theme:</span> {theme}
        </p>
        <p>
          <span className="font-semibold">Preferred Language:</span> {acceptLanguage || 'Not specified'}
        </p>
      </div>
    </div>
  )
}

